// Geographic coastlines are hand-simplified theatre sketches. Initial stations,
// flight groups and combat windows are adaptations, not historical track charts.
function chart(id,name,west,east,north,south,land,labels){
  const referenceLatitude=(north+south)/2,scale=60*Math.cos(referenceLatitude*Math.PI/180);
  return {id,name,west,east,north,south,referenceLatitude,width:(east-west)*scale,height:(north-south)*60,
    schematic:true,source:'按经纬度投影的简化作战海图；非精密航海图',
    land:land.map(poly=>poly.map(([lon,lat])=>[(lon-west)*scale,(north-lat)*60])),labels};
}

